 SkillSlotPlacement Place(SkillSlotsOptions o){int n=choices.FindIndex(s=>s.Index==selectedIndex);return n<0?new SkillSlotPlacement():o.Ensure(selectedIndex,n);}
 string Text(string value){return UiLanguage.Text(value,owner.Language);}
 string SkillName(SkillSlotsSignal.Slot slot){string name=SkillCatalogue.Shared.Name(slot.Skill,owner.Language);if(slot.Alternative!=0)name+=" / "+SkillCatalogue.Shared.Name(slot.Alternative,owner.Language);if(slot.Third!=0)name+=" / "+SkillCatalogue.Shared.Name(slot.Third,owner.Language);return name;}
 void Choices(SkillSlotsOptions o,List<SkillSlotsSignal.Slot> list,bool live){string next=owner.Language+"/"+string.Join(";",list.Select(s=>s.Index+":"+s.Skill+":"+s.Alternative+":"+s.Third+":"+o.Placement(s.Index,0).Visible));if(next!=choicesKey){choices=list;selected.Items.Clear();for(int n=0;n<list.Count;n++){var slot=list[n];var content=new StackPanel{Orientation=Orientation.Horizontal};var icon=painter.Assets.Icon(slot.Skill);if(icon!=null)content.Children.Add(new Image{Source=SettingsVisual.Bitmap(icon),Width=26,Height=26,Margin=new Thickness(0,0,8,0)});string title=Text("Slot")+" "+(n+1)+" · "+SkillCatalogue.Shared.Name(slot.Skill,owner.Language);if(!o.Placement(slot.Index,n).Visible)title+=" · "+Text("Hidden");var label=SettingsVisual.Text(title,12);label.MaxWidth=235;label.TextTrimming=TextTrimming.CharacterEllipsis;label.VerticalAlignment=VerticalAlignment.Center;content.Children.Add(label);selected.Items.Add(new ComboBoxItem{Tag=slot.Index,Content=content,ToolTip=SkillName(slot)});}
