 Grid Row(string label){var row=new Grid{Margin=new Thickness(0,5,0,5),MinHeight=35};row.ColumnDefinitions.Add(new ColumnDefinition());row.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});row.Children.Add(SettingsVisual.Text(label));return row;}
