 void Change(Action<SkillSlotsOptions> action){if(loading)return;var cfg=owner.Configuration;action(cfg.SkillSlots);cfg.SkillSlots.Normalize();owner.ApplyConfiguration(cfg);shown=null;Reload();}
 void Toggle(StackPanel group,string label,Func<SkillSlotsOptions,bool> read,Action<SkillSlotsOptions,bool> write){var row=Row(label);var box=new CheckBox();AutomationProperties.SetName(box,label);Grid.SetColumn(box,1);row.Children.Add(box);group.Children.Add(row);box.Click+=delegate{Change(o=>write(o,box.IsChecked==true));};reloaders.Add(o=>box.IsChecked=read(o));}
